1: 'use strict'
2: 
3: const { AsyncResource } = require('node:async_hooks')
4: const { FifoMap: Fifo } = require('toad-cache')
5: const { parse: secureJsonParse } = require('secure-json-parse')
6: const ContentType = require('./content-type')
7: const {
8:   kDefaultJsonParse,
9:   kContentTypeParser,
10:   kBodyLimit,
11:   kRequestPayloadStream,
12:   kState,
13:   kTestInternals,
14:   kReplyIsError,
15:   kRouteContext
16: } = require('./symbols')
17: 
18: const {
19:   FST_ERR_CTP_INVALID_TYPE,
20:   FST_ERR_CTP_EMPTY_TYPE,
21:   FST_ERR_CTP_ALREADY_PRESENT,
22:   FST_ERR_CTP_INVALID_HANDLER,
23:   FST_ERR_CTP_INVALID_PARSE_TYPE,
24:   FST_ERR_CTP_BODY_TOO_LARGE,
25:   FST_ERR_CTP_INVALID_MEDIA_TYPE,
26:   FST_ERR_CTP_INVALID_CONTENT_LENGTH,
27:   FST_ERR_CTP_EMPTY_JSON_BODY,
28:   FST_ERR_CTP_INSTANCE_ALREADY_STARTED,
29:   FST_ERR_CTP_INVALID_JSON_BODY
30: } = require('./errors')
31: const { FSTSEC001 } = require('./warnings')
32: 
33: function ContentTypeParser (bodyLimit, onProtoPoisoning, onConstructorPoisoning) {
34:   this[kDefaultJsonParse] = getDefaultJsonParser(onProtoPoisoning, onConstructorPoisoning)
35:   // using a map instead of a plain object to avoid prototype hijack attacks
36:   this.customParsers = new Map()
37:   this.customParsers.set('application/json', new Parser(true, false, bodyLimit, this[kDefaultJsonParse]))
38:   this.customParsers.set('text/plain', new Parser(true, false, bodyLimit, defaultPlainTextParser))
39:   this.parserList = ['application/json', 'text/plain']
40:   this.parserRegExpList = []
41:   this.cache = new Fifo(100)
42: }
43: 
44: ContentTypeParser.prototype.add = function (contentType, opts, parserFn) {
45:   const contentTypeIsString = typeof contentType === 'string'
46: 
47:   if (contentTypeIsString) {
48:     contentType = contentType.trim().toLowerCase()
49:     if (contentType.length === 0) throw new FST_ERR_CTP_EMPTY_TYPE()
50:   } else if (!(contentType instanceof RegExp)) {
51:     throw new FST_ERR_CTP_INVALID_TYPE()
52:   }
53: 
54:   if (typeof parserFn !== 'function') {
55:     throw new FST_ERR_CTP_INVALID_HANDLER()
56:   }
57: 
58:   if (this.existingParser(contentType)) {
59:     throw new FST_ERR_CTP_ALREADY_PRESENT(contentType)
60:   }
61: 
62:   if (opts.parseAs !== undefined) {
63:     if (opts.parseAs !== 'string' && opts.parseAs !== 'buffer') {
64:       throw new FST_ERR_CTP_INVALID_PARSE_TYPE(opts.parseAs)
65:     }
66:   }
67: 
68:   const parser = new Parser(
69:     opts.parseAs === 'string',
70:     opts.parseAs === 'buffer',
71:     opts.bodyLimit,
72:     parserFn
73:   )
74: 
75:   if (contentType === '*') {
76:     this.customParsers.set('', parser)
77:   } else {
78:     if (contentTypeIsString) {
79:       const ct = new ContentType(contentType)
80:       if (ct.isValid === false) {
81:         throw new FST_ERR_CTP_INVALID_TYPE()
82:       }
83:       const normalizedContentType = ct.toString()
84:       this.parserList.unshift(normalizedContentType)
85:       this.customParsers.set(normalizedContentType, parser)
86:     } else {
87:       validateRegExp(contentType)
88:       this.parserRegExpList.unshift(contentType)
89:       this.customParsers.set(contentType.toString(), parser)
90:     }
91:   }
92: }
93: 
94: ContentTypeParser.prototype.hasParser = function (contentType) {
95:   if (typeof contentType === 'string') {
96:     contentType = new ContentType(contentType).toString()
97:   } else {
98:     if (!(contentType instanceof RegExp)) throw new FST_ERR_CTP_INVALID_TYPE()
99:     contentType = contentType.toString()
100:   }
101: 
102:   return this.customParsers.has(contentType)
103: }
104: 
105: ContentTypeParser.prototype.existingParser = function (contentType) {
106:   if (typeof contentType === 'string') {
107:     const ct = new ContentType(contentType).toString()
108:     if (contentType === 'application/json' && this.customParsers.has(contentType)) {
109:       return this.customParsers.get(ct).fn !== this[kDefaultJsonParse]
110:     }
111:     if (contentType === 'text/plain' && this.customParsers.has(contentType)) {
112:       return this.customParsers.get(ct).fn !== defaultPlainTextParser
113:     }
114:   }
115: 
116:   return this.hasParser(contentType)
117: }
118: 
119: ContentTypeParser.prototype.getParser = function (contentType) {
120:   if (typeof contentType === 'string') {
121:     const cached = this.cache.get(contentType)
122:     if (cached !== undefined) return cached
123:     contentType = new ContentType(contentType)
124:   }
125:   const ct = contentType.toString()
126: 
127:   let parser = this.cache.get(ct)
128:   if (parser !== undefined) return parser
129:   parser = this.customParsers.get(ct)
130:   if (parser !== undefined) {
131:     this.cache.set(ct, parser)
132:     return parser
133:   }
134: 
135:   // We have conflicting desires across our test suite. In some cases, we
136:   // expect to get a parser by just passing the media-type. In others, we expect
137:   // to get a parser registered under the media-type while also providing
138:   // parameters. And in yet others, we expect to register a parser under the
139:   // media-type and have it apply to any request with a header that starts
140:   // with that type.
141:   parser = this.customParsers.get(contentType.mediaType)
142:   if (parser !== undefined) {
143:     this.cache.set(ct, parser)
144:     return parser
145:   }
146: 
147:   for (let j = 0; j !== this.parserRegExpList.length; ++j) {
148:     const parserRegExp = this.parserRegExpList[j]
149:     // A parser registered with a `g`/`y` flagged RegExp keeps a mutable
150:     // lastIndex between calls, so a plain `.test()` would skip part of the
151:     // next content type and match inconsistently. Reset it before testing.
152:     parserRegExp.lastIndex = 0
153:     if (parserRegExp.test(ct)) {
154:       parser = this.customParsers.get(parserRegExp.toString())
155:       this.cache.set(ct, parser)
156:       return parser
157:     }
158:   }
159: 
160:   return this.customParsers.get('')
161: }
162: 
163: ContentTypeParser.prototype.removeAll = function () {
164:   this.customParsers = new Map()
165:   this.parserRegExpList = []
166:   this.parserList = []
167:   this.cache = new Fifo(100)
168: }
169: 
170: ContentTypeParser.prototype.remove = function (contentType) {
171:   let parsers
172: 
173:   if (typeof contentType === 'string') {
174:     contentType = new ContentType(contentType).toString()
175:     parsers = this.parserList
176:   } else {
177:     if (!(contentType instanceof RegExp)) throw new FST_ERR_CTP_INVALID_TYPE()
178:     contentType = contentType.toString()
179:     parsers = this.parserRegExpList
180:   }
181: 
182:   const removed = this.customParsers.delete(contentType)
183:   const idx = parsers.findIndex(ct => ct.toString() === contentType)
184: 
185:   if (idx > -1) {
186:     parsers.splice(idx, 1)
187:   }
188: 
189:   return removed || idx > -1
190: }
191: 
192: ContentTypeParser.prototype.run = function (contentType, handler, request, reply) {
193:   const parser = this.getParser(contentType)
194: 
195:   if (parser === undefined) {
196:     if (request.is404 === true) {
197:       handler(request, reply)
198:       return
199:     }
200: 
201:     reply[kReplyIsError] = true
202:     reply.send(new FST_ERR_CTP_INVALID_MEDIA_TYPE())
203:     return
204:   }
205: 
206:   const resource = new AsyncResource('content-type-parser:run', request)
207: 
208:   // Preserve the request's async context without the per-request function
209:   // properties and wrappers created by AsyncResource.bind().
210:   function done (error, body) {
211:     resource.runInAsyncScope(onDone, undefined, error, body)
212:   }
213: 
214:   if (parser.asString === true || parser.asBuffer === true) {
215:     rawBody(
216:       request,
217:       reply,
218:       reply[kRouteContext]._parserOptions,
219:       parser,
220:       done
221:     )
222:     return
223:   }
224: 
225:   let result
226:   try {
227:     result = parser.fn(request, request[kRequestPayloadStream], done)
228:   } catch (error) {
229:     done(error, undefined)
230:     return
231:   }
232:   if (result && typeof result.then === 'function') {
233:     result.then(body => { done(null, body) }, done)
234:   }
235: 
236:   function onDone (error, body) {
237:     resource.emitDestroy()
238:     if (error != null) {
239:       // We must close the connection as the client may
240:       // send more data
241:       reply.header('connection', 'close')
242:       reply[kReplyIsError] = true
243:       reply.send(error)
244:       return
245:     }
246:     request.body = body
247:     handler(request, reply)
248:   }
249: }
250: 
251: function rawBody (request, reply, options, parser, done) {
252:   const asString = parser.asString === true
253:   const limit = options.limit === null ? parser.bodyLimit : options.limit
254:   const contentLength = Number(request.headers['content-length'])
255: 
256:   if (contentLength > limit) {
257:     done(new FST_ERR_CTP_BODY_TOO_LARGE(), undefined)
258:     return
259:   }
260: 
261:   let receivedLength = 0
262:   const chunks = []
263:   const payload = request[kRequestPayloadStream] || request.raw
264: 
265:   // Always read raw Buffers and decode once at the end: setEncoding() would
266:   // allocate a StringDecoder per request and force a Buffer.byteLength()
267:   // rescan of every decoded chunk just to enforce the byte limit.
268: 
269:   payload.on('data', onData)
270:   payload.on('end', onEnd)
271:   payload.on('error', onEnd)
272:   payload.resume()
273: 
274:   function onData (chunk) {
275:     // A custom preParsing stream may still emit strings
276:     if (typeof chunk === 'string') {
277:       chunk = Buffer.from(chunk)
278:     }
279:     receivedLength += chunk.length
280:     const { receivedEncodedLength = 0 } = payload
281:     // The resulting body length must not exceed bodyLimit (see "zip bomb").
282:     // The case when encoded length is larger than received length is rather theoretical,
283:     // unless the stream returned by preParsing hook is broken and reports wrong value.
284:     if (receivedLength > limit || receivedEncodedLength > limit) {
285:       payload.removeListener('data', onData)
286:       payload.removeListener('end', onEnd)
287:       payload.removeListener('error', onEnd)
288:       done(new FST_ERR_CTP_BODY_TOO_LARGE(), undefined)
289:       return
290:     }
291: 
292:     chunks.push(chunk)
293:   }
294: 
295:   function onEnd (err) {
296:     payload.removeListener('data', onData)
297:     payload.removeListener('end', onEnd)
298:     payload.removeListener('error', onEnd)
299: 
300:     if (err != null) {
301:       if (!(typeof err.statusCode === 'number' && err.statusCode >= 400)) {
302:         err.statusCode = 400
303:       }
304:       done(err, undefined)
305:       return
306:     }
307: 
308:     if (!Number.isNaN(contentLength) && (payload.receivedEncodedLength || receivedLength) !== contentLength) {
309:       done(new FST_ERR_CTP_INVALID_CONTENT_LENGTH(), undefined)
310:       return
311:     }
312: 
313:     let body
314:     if (asString) {
315:       // Decoding the whole body at once also keeps multi-byte characters
316:       // split across chunks intact
317:       body = chunks.length === 1
318:         ? chunks[0].toString('utf8')
319:         : Buffer.concat(chunks, receivedLength).toString('utf8')
320:     } else {
321:       // Always copy so the parser never receives a view over the shared
322:       // socket read buffer
323:       body = Buffer.concat(chunks, receivedLength)
324:     }
325: 
326:     let result
327:     try {
328:       result = parser.fn(request, body, done)
329:     } catch (error) {
330:       done(error, undefined)
331:       return
332:     }
333:     if (result && typeof result.then === 'function') {
334:       result.then(body => { done(null, body) }, done)
335:     }
336:   }
337: }
338: 
339: function getDefaultJsonParser (onProtoPoisoning, onConstructorPoisoning) {
340:   const parseOptions = { protoAction: onProtoPoisoning, constructorAction: onConstructorPoisoning }
341: 
342:   return defaultJsonParser
343: 
344:   function defaultJsonParser (req, body, done) {
345:     if (body.length === 0) {
346:       done(new FST_ERR_CTP_EMPTY_JSON_BODY(), undefined)
347:       return
348:     }
349:     try {
350:       done(null, secureJsonParse(body, parseOptions))
351:     } catch {
352:       done(new FST_ERR_CTP_INVALID_JSON_BODY(), undefined)
353:     }
354:   }
355: }
356: 
357: function defaultPlainTextParser (req, body, done) {
358:   done(null, body)
359: }
360: 
361: function Parser (asString, asBuffer, bodyLimit, fn) {
362:   this.asString = asString
363:   this.asBuffer = asBuffer
364:   this.bodyLimit = bodyLimit
365:   this.fn = fn
366: }
367: 
368: function buildContentTypeParser (c) {
369:   const contentTypeParser = new ContentTypeParser()
370:   contentTypeParser[kDefaultJsonParse] = c[kDefaultJsonParse]
371:   contentTypeParser.customParsers = new Map(c.customParsers.entries())
372:   contentTypeParser.parserList = c.parserList.slice()
373:   contentTypeParser.parserRegExpList = c.parserRegExpList.slice()
374:   return contentTypeParser
375: }
376: 
377: function addContentTypeParser (contentType, opts, parser) {
378:   if (this[kState].started) {
379:     throw new FST_ERR_CTP_INSTANCE_ALREADY_STARTED('addContentTypeParser')
380:   }
381: 
382:   if (typeof opts === 'function') {
383:     parser = opts
384:     opts = {}
385:   }
386: 
387:   if (!opts) opts = {}
388:   if (!opts.bodyLimit) opts.bodyLimit = this[kBodyLimit]
389: 
390:   if (Array.isArray(contentType)) {
391:     contentType.forEach((type) => this[kContentTypeParser].add(type, opts, parser))
392:   } else {
393:     this[kContentTypeParser].add(contentType, opts, parser)
394:   }
395: 
396:   return this
397: }
398: 
399: function hasContentTypeParser (contentType) {
400:   return this[kContentTypeParser].hasParser(contentType)
401: }
402: 
403: function removeContentTypeParser (contentType) {
404:   if (this[kState].started) {
405:     throw new FST_ERR_CTP_INSTANCE_ALREADY_STARTED('removeContentTypeParser')
406:   }
407: 
408:   if (Array.isArray(contentType)) {
409:     for (const type of contentType) {
410:       this[kContentTypeParser].remove(type)
411:     }
412:   } else {
413:     this[kContentTypeParser].remove(contentType)
414:   }
415: }
416: 
417: function removeAllContentTypeParsers () {
418:   if (this[kState].started) {
419:     throw new FST_ERR_CTP_INSTANCE_ALREADY_STARTED('removeAllContentTypeParsers')
420:   }
421: 
422:   this[kContentTypeParser].removeAll()
423: }
424: 
425: function validateRegExp (regexp) {
426:   // RegExp should either start with ^ or include ;?
427:   // It can ensure the user is properly detect the essence
428:   // MIME types.
429:   if (regexp.source[0] !== '^' && regexp.source.includes(';?') === false) {
430:     FSTSEC001(regexp.source)
431:   }
432: }
433: 
434: module.exports = ContentTypeParser
435: module.exports.helpers = {
436:   buildContentTypeParser,
437:   addContentTypeParser,
438:   hasContentTypeParser,
439:   removeContentTypeParser,
440:   removeAllContentTypeParsers
441: }
442: module.exports.defaultParsers = {
443:   getDefaultJsonParser,
444:   defaultTextParser: defaultPlainTextParser
445: }
446: module.exports[kTestInternals] = { rawBody }
